WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_proportion_two_period'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '两期比重', 'kp-xingce-data-proportion-two-period', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "两期比重比较"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "直接定性判断今年的比重相对去年的比重是上升了还是下降了。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题目问：“2023年某项指标占整体的比重，相比于2022年是上升了还是下降了？” 这是纯正的秒杀题，绝不需要动笔算！"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心口诀"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "部分增速 (a) > 整体增速 (b)，比重上升。", "marks": [{"type": "bold"}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "部分增速 (a) < 整体增速 (b)，比重下降。", "marks": [{"type": "bold"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[阅读题干认出两期比重] --> B[找出分子的增速 a]\nB --> C[找出分母的增速 b]\nC --> D{比较 a 和 b 的大小}\nD -- a > b --> E[秒选: 比重上升]\nD -- a < b --> F[秒选: 比重下降]\nD -- a = b --> G[秒选: 比重不变]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2023年进出口总额增 0.2%。其中，出口增 0.6%。问出口占比比上年？选项：A. 上升 B. 下降 C. 不变 D. 无法判断"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "分子增速 a：出口增速 0.6%。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "分母增速 b：进出口总额增速 0.2%。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "比较大小：a(0.6%) > b(0.2%)。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "出结论：部分跑得快，抢占的份额就大，比重上升。选 A。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "负数比较大小陷阱：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "如果 a 和 b 都是下降的（即负数），千万不要看绝对值比大小！必须带着负号比。比如 a = -5%，b = -10%。因为 -5% > -10%（虽然跌了，但跌得比大盘少），所以 a > b，比重依然是上升的！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "遇到这道题，必须在 5 秒内出答案，把时间留给那些难算的死题。"}]}]}$$ AS jsonb), NULL, '两期比重的核心考点与实战推导。', category_node.id, CAST('["资料分析", "两期比重"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_proportion_two_period", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
